   including the call and return. */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  int ii, jj;

  /* Hoist the constant stencil weight out of all loops. */
  const DATA_TYPE w = SCALAR_VAL(0.2);

  /* Local restrict-qualified aliases to help the compiler reason about
     aliasing and keep data in registers. A and B are distinct buffers
     in this benchmark, so this is semantically correct. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Tunable tile sizes. These values give good cache behavior on
     typical x86-64 CPUs while keeping the code simple. Adjust if needed. */
  const int TI = 32;  /* rows per tile  */
  const int TJ = 64;  /* cols per tile  */

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* ------------------------------------------------------------
       * Sweep 1: compute B from A (Jacobi update A -> B)
       *   B[i][j] = w * (A[i][j] + A[i][j-1] + A[i][j+1]
       *                   + A[i-1][j] + A[i+1][j]);
       * ------------------------------------------------------------ */
      for (ii = 1; ii < _PB_N - 1; ii += TI)
      {
        int i_max = ii + TI;
        if (i_max > _PB_N - 1)
          i_max = _PB_N - 1;

        for (jj = 1; jj < _PB_N - 1; jj += TJ)
        {
          int j_max = jj + TJ;
          if (j_max > _PB_N - 1)
            j_max = _PB_N - 1;

          for (i = ii; i < i_max; i++)
          {
            /* Row pointers for the current tile.
               Access pattern:
                 - Ai[j-1], Ai[j], Ai[j+1] : unit stride in j
                 - Aim1[j], Aip1[j]        : regular stride across rows */
