            const DATA_TYPE *restrict Ai   = A_[i];
            const DATA_TYPE *restrict Aim1 = A_[i-1];
            const DATA_TYPE *restrict Aip1 = A_[i+1];

            /* Inner-most loop: contiguous in memory, amenable to SIMD. */
#pragma GCC ivdep
            for (j = jj; j < j_max; j++)
            {
              DATA_TYPE center = Ai[j];
              DATA_TYPE left   = Ai[j-1];
              DATA_TYPE right  = Ai[j+1];
              DATA_TYPE up     = Aim1[j];
              DATA_TYPE down   = Aip1[j];

              Bi[j] = w * (center + left + right + up + down);
            }
          }
        }
      }

      /* ------------------------------------------------------------
       * Sweep 2: compute A from B (Jacobi update B -> A)
       *   A[i][j] = w * (B[i][j] + B[i][j-1] + B[i][j+1]
       *                   + B[i-1][j] + B[i+1][j]);
       * ------------------------------------------------------------ */
      for (ii = 1; ii < _PB_N - 1; ii += TI)
      {
        int i_max = ii + TI;
        if (i_max > _PB_N - 1)
          i_max = _PB_N - 1;

        for (jj = 1; jj < _PB_N - 1; jj += TJ)
        {
          int j_max = jj + TJ;
          if (j_max > _PB_N - 1)
            j_max = _PB_N - 1;

          for (i = ii; i < i_max; i++)
          {
            DATA_TYPE *restrict       Ai   = A_[i];
            const DATA_TYPE *restrict Bi   = B_[i];
            const DATA_TYPE *restrict Bim1 = B_[i-1];
            const DATA_TYPE *restrict Bip1 = B_[i+1];

#pragma GCC ivdep
            for (j = jj; j < j_max; j++)
            {
              DATA_TYPE center = Bi[j];
              DATA_TYPE left   = Bi[j-1];
              DATA_TYPE right  = Bi[j+1];
              DATA_TYPE up     = Bim1[j];
              DATA_TYPE down   = Bip1[j];

              Ai[j] = w * (center + left + right + up + down);
            }
          }
        }
      }
    }
#pragma endscop

}


