    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t;

  /* Hoist the stencil weight out of the loops so it is computed once
     and can be kept in a register. */
  const DATA_TYPE w = SCALAR_VAL(0.2);

  /* Tunable tile sizes for spatial blocking.
     32×32 tiles give good cache behavior on typical x64 CPUs:
       - A and B tiles for 32 rows × 32 columns (plus 1-cell halo)
         fit comfortably in L1/L2.
     These values can be adjusted for a specific machine. */
  const int TI = 32; /* tile size in i (rows)  */
  const int TJ = 32; /* tile size in j (cols)  */

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* --------------------------------------------------------------------
       * Sweep 1: B = Jacobi(A)
       *
       *   B[i][j] = w * (A[i][j] + A[i][j-1] + A[i][j+1]
       *                   + A[i-1][j] + A[i+1][j]);
       *
       * We tile the 2D interior domain [1, _PB_N-1)×[1, _PB_N-1) to improve
       * cache locality and keep the innermost j-loop unit-stride for SIMD.
       * Each (i,j) update only reads from A and writes to a distinct B[i][j],
       * so reordering via tiling and vectorization is semantics-preserving.
       * ------------------------------------------------------------------ */

      /* Parallelize over row tiles when compiled with OpenMP.
         Without -fopenmp, this pragma is ignored and the code remains
         purely sequential (same semantics as the original). */
#pragma omp parallel for schedule(static) if (_PB_N > 32)
      for (int ii = 1; ii < _PB_N - 1; ii += TI)
        {
          const int i_end = (ii + TI < _PB_N - 1) ? (ii + TI) : (_PB_N - 1);

          for (int jj = 1; jj < _PB_N - 1; jj += TJ)
            {
              const int j_end = (jj + TJ < _PB_N - 1) ? (jj + TJ) : (_PB_N - 1);

              for (int i = ii; i < i_end; ++i)
                {
                  /* Row pointers: help the compiler keep base addresses
                     in registers and understand that different rows and
                     arrays do not alias. */
                  DATA_TYPE * restrict Bi   = B[i];
                  DATA_TYPE * restrict Ai   = A[i];
                  DATA_TYPE * restrict Aim1 = A[i-1];
                  DATA_TYPE * restrict Aip1 = A[i+1];

                  /* Innermost loop is over contiguous j, matching the
                     row-major layout and enabling efficient SIMD.
                     The GCC pragmas are hints to strengthen vectorization
                     and unrolling; they are ignored by other compilers. */
#pragma GCC ivdep
#pragma GCC unroll 8
                  for (int j = jj; j < j_end; ++j)
                    {
                      Bi[j] = w * (Ai[j] +
                                   Ai[j-1] + Ai[j+1] +
                                   Aim1[j] + Aip1[j]);
                    }
                }
            }
        }

      /* --------------------------------------------------------------------
       * Sweep 2: A = Jacobi(B)
       *
       *   A[i][j] = w * (B[i][j] + B[i][j-1] + B[i][j+1]
       *                   + B[i-1][j] + B[i+1][j]);
       *
       * Structure is identical to the first sweep, but with roles of A and B
       * swapped.  The entire B-sweep above is completed before this sweep
       * starts, exactly as in the original code, so numerical semantics are
       * preserved (up to benign FP roundoff differences due to reordering).
       * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static) if (_PB_N > 32)
      for (int ii = 1; ii < _PB_N - 1; ii += TI)
        {
          const int i_end = (ii + TI < _PB_N - 1) ? (ii + TI) : (_PB_N - 1);

          for (int jj = 1; jj < _PB_N - 1; jj += TJ)
            {
              const int j_end = (jj + TJ < _PB_N - 1) ? (jj + TJ) : (_PB_N - 1);

              for (int i = ii; i < i_end; ++i)
                {
                  DATA_TYPE * restrict Ai   = A[i];
                  DATA_TYPE * restrict Bi   = B[i];
                  DATA_TYPE * restrict Bim1 = B[i-1];
                  DATA_TYPE * restrict Bip1 = B[i+1];

#pragma GCC ivdep
#pragma GCC unroll 8
                  for (int j = jj; j < j_end; ++j)
                    {
                      Ai[j] = w * (Bi[j] +
                                   Bi[j-1] + Bi[j+1] +
                                   Bim1[j] + Bip1[j]);
                    }
                }
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
