    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

  /* Local restrict-qualified views of A and B.
   * POLYBENCH_2D(A,...) expands to a VLA type; we create pointer
   * aliases with explicit restrict to tell the compiler there is no
   * aliasing between A and B, which helps vectorization and
   * reordering.
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Stencil weight, computed once and kept in a register. */
  const DATA_TYPE w = SCALAR_VAL(0.2);

  /* Interior region bounds (Dirichlet boundaries at index 0 and n-1). */
  const int i_start = 1;
  const int i_end   = _PB_N - 1; /* exclusive upper bound: interior rows are [1, _PB_N-1) */
  const int j_start = 1;
  const int j_end   = _PB_N - 1; /* exclusive upper bound: interior cols are [1, _PB_N-1) */

  /* Tile sizes in each spatial dimension. */
  const int TI = JACOBI_2D_TILE_I;
  const int TJ = JACOBI_2D_TILE_J;

#pragma scop
  /* Time loop must remain sequential: each step depends on the previous. */
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      /* ----------------------------------------------------------------
       * Sweep 1: compute B from A using a 5-point Jacobi stencil.
       *
       * We apply 2D spatial blocking on (i, j):
       *   - Outer loops (ii, jj) iterate over tiles.
       *   - Inner loops (i, j) iterate within a tile.
       *
       * This improves cache locality by keeping small sub-blocks of A
       * and B in cache while computing all their updates.
       * ---------------------------------------------------------------- */
      for (int ii = i_start; ii < i_end; ii += TI)
      {
        const int i_tile_end = (ii + TI < i_end) ? (ii + TI) : i_end;

        for (int jj = j_start; jj < j_end; jj += TJ)
        {
          const int j_tile_end = (jj + TJ < j_end) ? (jj + TJ) : j_end;

          for (i = ii; i < i_tile_end; ++i)
          {
            /* Cache row pointers for the current and neighboring rows.
             * This reduces address arithmetic in the inner loop and
             * keeps accesses simple and unit-stride in j.
             */
            DATA_TYPE       *restrict Bi   = B_[i];
            const DATA_TYPE *restrict Ai   = A_[i];
            const DATA_TYPE *restrict Aim1 = A_[i - 1];
            const DATA_TYPE *restrict Aip1 = A_[i + 1];

            /* j-loop is innermost and contiguous in memory: ideal for SIMD.
             * The ivdep pragma tells GCC that iterations are independent
             * (true here because we only read from A_ rows and write to Bi).
             */
#pragma GCC ivdep
            for (j = jj; j < j_tile_end; ++j)
            {
              const DATA_TYPE center = Ai[j];
              const DATA_TYPE left   = Ai[j - 1];
              const DATA_TYPE right  = Ai[j + 1];
              const DATA_TYPE up     = Aim1[j];
              const DATA_TYPE down   = Aip1[j];

              Bi[j] = w * (center + left + right + up + down);
            }
          }
        }
      }

      /* ----------------------------------------------------------------
       * Sweep 2: compute A from B using the same stencil.
       *
       * The entire B grid for time step t has been computed above
       * before we start updating A, preserving the original program's
       * ordering (all B-updates at t, then all A-updates at t).
       *
       * We reuse the same tiling structure for good locality.
       * ---------------------------------------------------------------- */
      for (int ii = i_start; ii < i_end; ii += TI)
      {
        const int i_tile_end = (ii + TI < i_end) ? (ii + TI) : i_end;

        for (int jj = j_start; jj < j_end; jj += TJ)
        {
          const int j_tile_end = (jj + TJ < j_end) ? (jj + TJ) : j_end;

          for (i = ii; i < i_tile_end; ++i)
          {
            DATA_TYPE       *restrict Ai   = A_[i];
            const DATA_TYPE *restrict Bi   = B_[i];
            const DATA_TYPE *restrict Bim1 = B_[i - 1];
            const DATA_TYPE *restrict Bip1 = B_[i + 1];

#pragma GCC ivdep
            for (j = jj; j < j_tile_end; ++j)
            {
              const DATA_TYPE center = Bi[j];
              const DATA_TYPE left   = Bi[j - 1];
              const DATA_TYPE right  = Bi[j + 1];
              const DATA_TYPE up     = Bim1[j];
              const DATA_TYPE down   = Bip1[j];

              Ai[j] = w * (center + left + right + up + down);
            }
          }
        }
      }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}

