/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving semantics):
   - Hoist constant stencil weight (0.2) out of loops.
   - Create local restrict-qualified row-major pointers A_/B_ to
     help the compiler with alias analysis and vectorization.
   - 2D spatial blocking (tiling) over i and j to improve cache reuse.
   - Keep j as the innermost loop for unit-stride, SIMD-friendly access.
   - Use row pointers (Ai, Aim1, Aip1, ...) to avoid repeated index
     computations inside the inner loop.
   - Optional OpenMP pragmas to parallelize over tiles when compiled
     with -fopenmp; otherwise they are ignored and the code remains
     sequential but still optimized for cache and SIMD.
 */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

  /* Local restrict-qualified views of the 2D arrays.
     The polybench macro expands A and B as n-by-n VLAs; we create
     pointer aliases annotated with restrict to help the optimizer. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Stencil weight: identical to the original SCALAR_VAL(0.2),
     but computed once and reused. */
  const DATA_TYPE w = SCALAR_VAL(0.2);

  /* Tunable tile sizes for spatial blocking.
     These values are chosen to keep a tile (plus its halo) in L1/L2 cache
     on typical x64 CPUs; they can be adjusted if needed. */
  const int TI = 32;
  const int TJ = 32;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      int ii, jj;

      /* -------------------------------------------------------- */
      /* Sweep 1: B = Jacobi(A)
         B[i][j] = w * (A[i][j] + A[i][j-1] + A[i][j+1]
                        + A[i-1][j] + A[i+1][j]);
         Only interior points 1.._PB_N-2 are updated, matching the
         original code. Tiles are processed in any order; all updates
         are independent within this sweep because A is read-only.    */
      /* -------------------------------------------------------- */
      #pragma omp parallel for collapse(2) private(i,j) schedule(static)
      for (ii = 1; ii < _PB_N - 1; ii += TI)
        for (jj = 1; jj < _PB_N - 1; jj += TJ)
        {
          const int i_end = (ii + TI < _PB_N - 1) ? (ii + TI) : (_PB_N - 1);
          const int j_end = (jj + TJ < _PB_N - 1) ? (jj + TJ) : (_PB_N - 1);

          for (i = ii; i < i_end; ++i)
          {
            DATA_TYPE *restrict       Bi   = B_[i];
            const DATA_TYPE *restrict Ai   = A_[i];
            const DATA_TYPE *restrict Aim1 = A_[i-1];
            const DATA_TYPE *restrict Aip1 = A_[i+1];

            /* j is innermost: unit-stride access in row-major layout.
               The compiler can auto-vectorize this loop efficiently. */
            #pragma GCC ivdep
            for (j = jj; j < j_end; ++j)
            {
              Bi[j] = w * ( Ai[j]   +
                            Ai[j-1] +
                            Ai[j+1] +
                            Aim1[j] +
                            Aip1[j] );
            }
          }
        }

      /* -------------------------------------------------------- */
      /* Sweep 2: A = Jacobi(B)
         A[i][j] = w * (B[i][j] + B[i][j-1] + B[i][j+1]
                        + B[i-1][j] + B[i+1][j]);
         As in the original, the entire B grid for time step t is
         computed before any A update at step t; the two sweeps are
         kept as separate loops with an implicit barrier between them. */
      /* -------------------------------------------------------- */
      #pragma omp parallel for collapse(2) private(i,j) schedule(static)
      for (ii = 1; ii < _PB_N - 1; ii += TI)
        for (jj = 1; jj < _PB_N - 1; jj += TJ)
        {
          const int i_end = (ii + TI < _PB_N - 1) ? (ii + TI) : (_PB_N - 1);
          const int j_end = (jj + TJ < _PB_N - 1) ? (jj + TJ) : (_PB_N - 1);

          for (i = ii; i < i_end; ++i)
          {
            DATA_TYPE *restrict       Ai   = A_[i];
            const DATA_TYPE *restrict Bi   = B_[i];
            const DATA_TYPE *restrict Bim1 = B_[i-1];
            const DATA_TYPE *restrict Bip1 = B_[i+1];

            #pragma GCC ivdep
            for (j = jj; j < j_end; ++j)
            {
              Ai[j] = w * ( Bi[j]   +
                            Bi[j-1] +
                            Bi[j+1] +
                            Bim1[j] +
                            Bip1[j] );
            }
          }
        }
    }
#pragma endscop

  (void)tsteps; /* tsteps is equal to TSTEPS; silence potential unused warning. */
}


